use std::{
    fs::{self, File, OpenOptions},
    io::{self, Read, Write},
    path::Path,
};

fn main() {
    let metadata = fs::metadata("hello.txt").unwrap();
    println!("Is read only: {}", metadata.permissions().readonly());
    println!("Is file: {}", metadata.is_file());
    println!("Is dir: {}", metadata.is_dir());
    println!("File size: {}", metadata.len());
    println!("Modified: {:?}", metadata.modified().unwrap());
    println!("Created: {:?}", metadata.created().unwrap());
    println!("Accessed: {:?}", metadata.accessed().unwrap());
    println!("File type: {:?}", metadata.file_type());
}

